package live.linghe.privateinput;
import java.util.*;
public final class SymbolGlyphParityTest {
 static int checks;static void ok(boolean b,String label){checks++;if(!b)throw new AssertionError(label);}
 public static void main(String[] args){String[] open={"(","（","[","【","{","《","〈","「","『","“","‘","\""},closed={")","）","]","】","}","》","〉","」","』","”","’","\""};for(int i=0;i<open.length;i++){SymbolPairing.Plan plan=SymbolPairing.plan(open[i],true,true);ok(plan.insertedText.equals(open[i]+closed[i])&&plan.caretBack==1,"paired and inside "+open[i]);plan=SymbolPairing.plan(open[i],true,false);ok(plan.insertedText.equals(open[i]+closed[i])&&plan.caretBack==0,"paired and after "+open[i]);plan=SymbolPairing.plan(open[i],false,true);ok(plan.insertedText.equals(open[i])&&plan.caretBack==0,"pairing disabled "+open[i]);}for(String raw:new String[]{"'","()","【你好】","apple","。","@","1.4",","}){SymbolPairing.Plan plan=SymbolPairing.plan(raw,true,true);ok(plan.insertedText.equals(raw)&&plan.caretBack==0,"raw/multiple text unchanged");}
  ok(GlyphAvailability.displayable("你好",point->point==0x4f60||point==0x597d),"phrase checked one scalar at a time");ok(!GlyphAvailability.displayable("你𨈖",point->point==0x4f60),"unsupported supplementary scalar filtered");ok(!GlyphAvailability.displayable("\ud840",point->true),"unpaired surrogate rejected");ok(GlyphAvailability.displayable("（）",point->true),"normal punctuation retained");ok(GlyphAvailability.displayable("☀️",point->point==0x2600),"variation selector does not require standalone glyph");ok(!GlyphAvailability.displayable("",point->true),"empty candidate hidden");System.out.println("PASS "+checks+" Android symbol/glyph checks");}
}
